   223→+// calculateTokenUsage calculates token usage from raw transcript data.
   224→+// startOffset is the line number (Claude Code) or message index (Gemini CLI)
   225→+// where the current checkpoint began, allowing calculation for only the portion
   226→+// of the transcript since the last checkpoint.
   227→+func calculateTokenUsage(agentType agent.AgentType, data []byte, startOffset int) *agent.TokenUsage {
   228→+	if len(data) == 0 {
   229→+		return &agent.TokenUsage{}
   230→+	}
   231→+
   232→+	// Try Gemini format first if agentType is Gemini, or as fallback if Unknown
   233→+	if agentType == agent.AgentTypeGemini || agentType == agent.AgentTypeUnknown {
   234→+		// Attempt to parse as Gemini JSON
   235→+		transcript, err := geminicli.ParseTranscript(data)
   236→+		if err == nil && transcript != nil && len(transcript.Messages) > 0 {
   237→+			return geminicli.CalculateTokenUsage(data, startOffset)
   238→+		}
   239→+		// If agentType is explicitly Gemini but parsing failed, return empty usage
   240→+		if agentType == agent.AgentTypeGemini {
   241→+			return &agent.TokenUsage{}
   242→+		}
   243→+		// Otherwise fall through to JSONL parsing for Unknown type
   244→+	}
   245→+
   246→+	// Claude Code and other JSONL-based agents
   247→+	lines, err := claudecode.ParseTranscript(data)
   248→+	if err != nil || len(lines) == 0 {
   249→+		return &agent.TokenUsage{}
   250→+	}
   251→+	// Slice transcript lines to only include checkpoint portion
   252→+	if startOffset > 0 && startOffset < len(lines) {
   253→+		lines = lines[startOffset:]
   254→+	}
   255→+	return claudecode.CalculateTokenUsage(lines)
   256→ }
