   109→func (s *ManualCommitStrategy) CondenseSession(repo *git.Repository, checkpointID id.CheckpointID, state *SessionState) (*CondenseResult, error) {
   110→	// Get shadow branch
   111→	shadowBranchName := getShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
   112→	refName := plumbing.NewBranchReferenceName(shadowBranchName)
   113→	ref, err := repo.Reference(refName, true)
   114→	if err != nil {
   115→		return nil, fmt.Errorf("shadow branch not found: %w", err)
   116→	}
   117→
   118→	// Extract session data from the shadow branch (with live transcript fallback).
   119→	// Use tracked files from session state instead of collecting all files from tree.
   120→	// Pass agent type to handle different transcript formats (JSONL for Claude, JSON for Gemini).
   121→	// Pass live transcript path so condensation reads the current file rather than a
   122→	// potentially stale shadow branch copy (SaveChanges may have been skipped if the
   123→	// last turn had no code changes).
   124→	// Pass CheckpointTranscriptStart for accurate token calculation (line offset for Claude, message index for Gemini).
   125→	sessionData, err := s.extractSessionData(repo, ref.Hash(), state.SessionID, state.FilesTouched, state.AgentType, state.TranscriptPath, state.CheckpointTranscriptStart)
   126→	if err != nil {
   127→		return nil, fmt.Errorf("failed to extract session data: %w", err)
   128→	}
   129→
   130→	// Get checkpoint store
   131→	store, err := s.getCheckpointStore()
   132→	if err != nil {
   133→		return nil, fmt.Errorf("failed to get checkpoint store: %w", err)
   134→	}
   135→
   136→	// Get author info
   137→	authorName, authorEmail := GetGitAuthorFromRepo(repo)
   138→	attribution := calculateSessionAttributions(repo, ref, sessionData, state)
   139→	// Get current branch name
   140→	branchName := GetCurrentBranchName(repo)
   141→
   142→	// Generate summary if enabled
   143→	var summary *cpkg.Summary
   144→	if settings.IsSummarizeEnabled() && len(sessionData.Transcript) > 0 {
   145→		logCtx := logging.WithComponent(context.Background(), "attribution")
   146→		summarizeCtx := logging.WithComponent(logCtx, "summarize")
   147→
   148→		// Scope transcript to this checkpoint's portion.
   149→		// SliceFromLine only works for JSONL (Claude Code) transcripts where
   150→		// CheckpointTranscriptStart is a line offset. For Gemini JSON transcripts,
   151→		// CheckpointTranscriptStart is a message index and the transcript is a single
   152→		// JSON blob, so line-based slicing would produce malformed content.
   153→		// The summarizer (ParseFromBytes) only supports JSONL, so skip scoping for Gemini.
   154→		var scopedTranscript []byte
   155→		if state.AgentType == agent.AgentTypeGemini {
   156→			scopedTranscript = sessionData.Transcript
   157→		} else {
   158→			scopedTranscript = transcript.SliceFromLine(sessionData.Transcript, state.CheckpointTranscriptStart)
   159→		}
   160→		if len(scopedTranscript) > 0 {
   161→			var err error
   162→			summary, err = summarize.GenerateFromTranscript(summarizeCtx, scopedTranscript, sessionData.FilesTouched, nil)
   163→			if err != nil {
   164→				logging.Warn(summarizeCtx, "summary generation failed",
   165→					slog.String("session_id", state.SessionID),
   166→					slog.String("error", err.Error()))
   167→				// Continue without summary - non-blocking
   168→			} else {
   169→				logging.Info(summarizeCtx, "summary generated",
   170→					slog.String("session_id", state.SessionID))
   171→			}
   172→		}
   173→	}
   174→
   175→	// Write checkpoint metadata using the checkpoint store
   176→	if err := store.WriteCommitted(context.Background(), cpkg.WriteCommittedOptions{
   177→		CheckpointID:                checkpointID,
   178→		SessionID:                   state.SessionID,
   179→		Strategy:                    StrategyNameManualCommit,
   180→		Branch:                      branchName,
   181→		Transcript:                  sessionData.Transcript,
   182→		Prompts:                     sessionData.Prompts,
   183→		Context:                     sessionData.Context,
   184→		FilesTouched:                sessionData.FilesTouched,
   185→		CheckpointsCount:            state.StepCount,
   186→		EphemeralBranch:             shadowBranchName,
   187→		AuthorName:                  authorName,
   188→		AuthorEmail:                 authorEmail,
   189→		Agent:                       state.AgentType,
   190→		TranscriptIdentifierAtStart: state.TranscriptIdentifierAtStart,
   191→		CheckpointTranscriptStart:   state.CheckpointTranscriptStart,
   192→		TokenUsage:                  sessionData.TokenUsage,
   193→		InitialAttribution:          attribution,
   194→		Summary:                     summary,
   195→	}); err != nil {
   196→		return nil, fmt.Errorf("failed to write checkpoint metadata: %w", err)
   197→	}
   198→
   199→	return &CondenseResult{
   200→		CheckpointID:         checkpointID,
   201→		SessionID:            state.SessionID,
   202→		CheckpointsCount:     state.StepCount,
   203→		FilesTouched:         sessionData.FilesTouched,
   204→		TotalTranscriptLines: sessionData.FullTranscriptLines,
   205→	}, nil
   206→}
   207→
   208→func calculateSessionAttributions(repo *git.Repository, shadowRef *plumbing.Reference, sessionData *ExtractedSessionData, state *SessionState) *cpkg.InitialAttribution {
   209→	// Calculate initial attribution using accumulated prompt attribution data.
   210→	// This uses user edits captured at each prompt start (before agent works),
   211→	// plus any user edits after the final checkpoint (shadow → head).
   212→	logCtx := logging.WithComponent(context.Background(), "attribution")
   213→	var attribution *cpkg.InitialAttribution
   214→	headRef, headErr := repo.Head()
   215→	if headErr != nil {
   216→		logging.Debug(logCtx, "attribution skipped: failed to get HEAD",
   217→			slog.String("error", headErr.Error()))
   218→	} else {
   219→		headCommit, commitErr := repo.CommitObject(headRef.Hash())
   220→		if commitErr != nil {
   221→			logging.Debug(logCtx, "attribution skipped: failed to get HEAD commit",
   222→				slog.String("error", commitErr.Error()))
   223→		} else {
   224→			headTree, treeErr := headCommit.Tree()
   225→			if treeErr != nil {
   226→				logging.Debug(logCtx, "attribution skipped: failed to get HEAD tree",
   227→					slog.String("error", treeErr.Error()))
   228→			} else {
   229→				// Get shadow branch tree (checkpoint tree - what the agent wrote)
   230→				shadowCommit, shadowErr := repo.CommitObject(shadowRef.Hash())
   231→				if shadowErr != nil {
   232→					logging.Debug(logCtx, "attribution skipped: failed to get shadow commit",
   233→						slog.String("error", shadowErr.Error()),
   234→						slog.String("shadow_ref", shadowRef.Hash().String()))
   235→				} else {
   236→					shadowTree, shadowTreeErr := shadowCommit.Tree()
   237→					if shadowTreeErr != nil {
   238→						logging.Debug(logCtx, "attribution skipped: failed to get shadow tree",
   239→							slog.String("error", shadowTreeErr.Error()))
   240→					} else {
   241→						// Get base tree (state before session started)
   242→						var baseTree *object.Tree
   243→						if baseCommit, baseErr := repo.CommitObject(plumbing.NewHash(state.BaseCommit)); baseErr == nil {
   244→							if tree, baseTErr := baseCommit.Tree(); baseTErr == nil {
   245→								baseTree = tree
   246→							} else {
   247→								logging.Debug(logCtx, "attribution: base tree unavailable",
   248→									slog.String("error", baseTErr.Error()))
   249→							}
   250→						} else {
   251→							logging.Debug(logCtx, "attribution: base commit unavailable",
   252→								slog.String("error", baseErr.Error()),
   253→								slog.String("base_commit", state.BaseCommit))
   254→						}
   255→
   256→						// Log accumulated prompt attributions for debugging
   257→						var totalUserAdded, totalUserRemoved int
   258→						for i, pa := range state.PromptAttributions {
   259→							totalUserAdded += pa.UserLinesAdded
   260→							totalUserRemoved += pa.UserLinesRemoved
   261→							logging.Debug(logCtx, "prompt attribution data",
   262→								slog.Int("checkpoint", pa.CheckpointNumber),
   263→								slog.Int("user_added", pa.UserLinesAdded),
   264→								slog.Int("user_removed", pa.UserLinesRemoved),
   265→								slog.Int("agent_added", pa.AgentLinesAdded),
   266→								slog.Int("agent_removed", pa.AgentLinesRemoved),
   267→								slog.Int("index", i))
   268→						}
   269→
   270→						attribution = CalculateAttributionWithAccumulated(
   271→							baseTree,
   272→							shadowTree,
   273→							headTree,
   274→							sessionData.FilesTouched,
   275→							state.PromptAttributions,
   276→						)
   277→
   278→						if attribution != nil {
   279→							logging.Info(logCtx, "attribution calculated",
   280→								slog.Int("agent_lines", attribution.AgentLines),
   281→								slog.Int("human_added", attribution.HumanAdded),
   282→								slog.Int("human_modified", attribution.HumanModified),
   283→								slog.Int("human_removed", attribution.HumanRemoved),
   284→								slog.Int("total_committed", attribution.TotalCommitted),
   285→								slog.Float64("agent_percentage", attribution.AgentPercentage),
   286→								slog.Int("accumulated_user_added", totalUserAdded),
   287→								slog.Int("accumulated_user_removed", totalUserRemoved),
   288→								slog.Int("files_touched", len(sessionData.FilesTouched)))
   289→						}
   290→					}
   291→				}
   292→			}
   293→		}
   294→	}
   295→	return attribution
   296→}
