   298→// extractSessionData extracts session data from the shadow branch.
   299→// filesTouched is the list of files tracked during the session (from SessionState.FilesTouched).
   300→// agentType identifies the agent (e.g., "Gemini CLI", "Claude Code") to determine transcript format.
   301→// liveTranscriptPath, when non-empty and readable, is preferred over the shadow branch copy.
   302→// This handles the case where SaveChanges was skipped (no code changes) but the transcript
   303→// continued growing — the shadow branch copy would be stale.
   304→// checkpointTranscriptStart is the line offset (Claude) or message index (Gemini) where the current checkpoint began.
   305→func (s *ManualCommitStrategy) extractSessionData(repo *git.Repository, shadowRef plumbing.Hash, sessionID string, filesTouched []string, agentType agent.AgentType, liveTranscriptPath string, checkpointTranscriptStart int) (*ExtractedSessionData, error) {
   306→	commit, err := repo.CommitObject(shadowRef)
   307→	if err != nil {
   308→		return nil, fmt.Errorf("failed to get commit object: %w", err)
   309→	}
   310→
   311→	tree, err := commit.Tree()
   312→	if err != nil {
   313→		return nil, fmt.Errorf("failed to get commit tree: %w", err)
   314→	}
   315→
   316→	data := &ExtractedSessionData{}
   317→	// sessionID is already an "entire session ID" (with date prefix)
   318→	metadataDir := paths.SessionMetadataDirFromSessionID(sessionID)
   319→
   320→	// Extract transcript — prefer the live file when available, fall back to shadow branch.
   321→	// The shadow branch copy may be stale if the last turn ended without code changes
   322→	// (SaveChanges is only called when there are file modifications).
   323→	var fullTranscript string
   324→	if liveTranscriptPath != "" {
   325→		if liveData, readErr := os.ReadFile(liveTranscriptPath); readErr == nil && len(liveData) > 0 { //nolint:gosec // path from session state
   326→			fullTranscript = string(liveData)
   327→		}
   328→	}
   329→	if fullTranscript == "" {
   330→		// Fall back to shadow branch copy
   331→		if file, fileErr := tree.File(metadataDir + "/" + paths.TranscriptFileName); fileErr == nil {
   332→			if content, contentErr := file.Contents(); contentErr == nil {
   333→				fullTranscript = content
   334→			}
   335→		} else if file, fileErr := tree.File(metadataDir + "/" + paths.TranscriptFileNameLegacy); fileErr == nil {
   336→			if content, contentErr := file.Contents(); contentErr == nil {
   337→				fullTranscript = content
   338→			}
   339→		}
   340→	}
   341→
   342→	// Process transcript based on agent type
   343→	if fullTranscript != "" {
   344→		data.Transcript = []byte(fullTranscript)
   345→		data.FullTranscriptLines = countTranscriptItems(agentType, fullTranscript)
   346→		data.Prompts = extractUserPrompts(agentType, fullTranscript)
   347→		data.Context = generateContextFromPrompts(data.Prompts)
   348→	}
   349→
   350→	// Use tracked files from session state (not all files in tree)
   351→	data.FilesTouched = filesTouched
   352→
   353→	// Calculate token usage from the extracted transcript portion
   354→	if len(data.Transcript) > 0 {
   355→		data.TokenUsage = calculateTokenUsage(agentType, data.Transcript, checkpointTranscriptStart)
   356→	}
   357→
   358→	return data, nil
   359→}
   360→
   361→// countTranscriptItems counts lines (JSONL) or messages (JSON) in a transcript.
   362→// For Claude Code and JSONL-based agents, this counts lines.
   363→// For Gemini CLI and JSON-based agents, this counts messages.
   364→// Returns 0 if the content is empty or malformed.
   365→func countTranscriptItems(agentType agent.AgentType, content string) int {
   366→	if content == "" {
   367→		return 0
   368→	}
   369→
   370→	// Try Gemini format first if agentType is Gemini, or as fallback if Unknown
   371→	if agentType == agent.AgentTypeGemini || agentType == agent.AgentTypeUnknown {
   372→		transcript, err := geminicli.ParseTranscript([]byte(content))
   373→		if err == nil && transcript != nil && len(transcript.Messages) > 0 {
   374→			return len(transcript.Messages)
   375→		}
   376→		// If agentType is explicitly Gemini but parsing failed, return 0
   377→		if agentType == agent.AgentTypeGemini {
   378→			return 0
   379→		}
   380→		// Otherwise fall through to JSONL parsing for Unknown type
   381→	}
   382→
   383→	// Claude Code and other JSONL-based agents
   384→	allLines := strings.Split(content, "\n")
   385→	// Trim trailing empty lines (from final \n in JSONL)
   386→	for len(allLines) > 0 && strings.TrimSpace(allLines[len(allLines)-1]) == "" {
   387→		allLines = allLines[:len(allLines)-1]
   388→	}
   389→	return len(allLines)
   390→}
   391→
   392→// extractUserPrompts extracts all user prompts from transcript content.
   393→// Returns prompts with IDE context tags stripped (e.g., <ide_opened_file>).
   394→func extractUserPrompts(agentType agent.AgentType, content string) []string {
   395→	if content == "" {
   396→		return nil
   397→	}
   398→
   399→	// Try Gemini format first if agentType is Gemini, or as fallback if Unknown
   400→	if agentType == agent.AgentTypeGemini || agentType == agent.AgentTypeUnknown {
   401→		prompts, err := geminicli.ExtractAllUserPrompts([]byte(content))
   402→		if err == nil && len(prompts) > 0 {
   403→			// Strip IDE context tags for consistency with Claude Code handling
   404→			cleaned := make([]string, 0, len(prompts))
   405→			for _, prompt := range prompts {
   406→				if stripped := textutil.StripIDEContextTags(prompt); stripped != "" {
   407→					cleaned = append(cleaned, stripped)
   408→				}
   409→			}
   410→			return cleaned
   411→		}
   412→		// If agentType is explicitly Gemini but parsing failed, return nil
   413→		if agentType == agent.AgentTypeGemini {
   414→			return nil
   415→		}
   416→		// Otherwise fall through to JSONL parsing for Unknown type
   417→	}
   418→
   419→	// Claude Code and other JSONL-based agents
   420→	return extractUserPromptsFromLines(strings.Split(content, "\n"))
   421→}
   422→
   423→// calculateTokenUsage calculates token usage from raw transcript data.
   424→// startOffset is the line number (Claude Code) or message index (Gemini CLI)
   425→// where the current checkpoint began, allowing calculation for only the portion
   426→// of the transcript since the last checkpoint.
   427→func calculateTokenUsage(agentType agent.AgentType, data []byte, startOffset int) *agent.TokenUsage {
   428→	if len(data) == 0 {
   429→		return &agent.TokenUsage{}
   430→	}
   431→
   432→	// Try Gemini format first if agentType is Gemini, or as fallback if Unknown
   433→	if agentType == agent.AgentTypeGemini || agentType == agent.AgentTypeUnknown {
   434→		// Attempt to parse as Gemini JSON
   435→		transcript, err := geminicli.ParseTranscript(data)
   436→		if err == nil && transcript != nil && len(transcript.Messages) > 0 {
   437→			return geminicli.CalculateTokenUsage(data, startOffset)
   438→		}
   439→		// If agentType is explicitly Gemini but parsing failed, return empty usage
   440→		if agentType == agent.AgentTypeGemini {
   441→			return &agent.TokenUsage{}
   442→		}
   443→		// Otherwise fall through to JSONL parsing for Unknown type
   444→	}
   445→
   446→	// Claude Code and other JSONL-based agents
   447→	lines, err := claudecode.ParseTranscript(data)
   448→	if err != nil || len(lines) == 0 {
   449→		return &agent.TokenUsage{}
   450→	}
   451→	// Slice transcript lines to only include checkpoint portion
   452→	if startOffset > 0 && startOffset < len(lines) {
   453→		lines = lines[startOffset:]
   454→	}
   455→	return claudecode.CalculateTokenUsage(lines)
   456→}
   457→
   458→// extractUserPromptsFromLines extracts user prompts from JSONL transcript lines.
   459→// IDE-injected context tags (like <ide_opened_file>) are stripped from the results.
   460→func extractUserPromptsFromLines(lines []string) []string {
   461→	var prompts []string
   462→	for _, line := range lines {
   463→		line = strings.TrimSpace(line)
   464→		if line == "" {
   465→			continue
   466→		}
   467→
   468→		var entry map[string]interface{}
   469→		if err := json.Unmarshal([]byte(line), &entry); err != nil {
   470→			continue
   471→		}
   472→
   473→		// Check for user message (supports both "human" and "user" types)
   474→		msgType, ok := entry["type"].(string)
   475→		if !ok || (msgType != "human" && msgType != "user") {
   476→			continue
   477→		}
   478→
   479→		// Extract message content
   480→		message, ok := entry["message"].(map[string]interface{})
   481→		if !ok {
   482→			continue
   483→		}
   484→
   485→		// Handle string content
   486→		if content, ok := message["content"].(string); ok && content != "" {
   487→			cleaned := textutil.StripIDEContextTags(content)
   488→			if cleaned != "" {
   489→				prompts = append(prompts, cleaned)
   490→			}
   491→			continue
   492→		}
   493→
   494→		// Handle array content (e.g., multiple text blocks from VSCode)
   495→		if arr, ok := message["content"].([]interface{}); ok {
   496→			var texts []string
   497→			for _, item := range arr {
   498→				if m, ok := item.(map[string]interface{}); ok {
   499→					if m["type"] == "text" {
   500→						if text, ok := m["text"].(string); ok {
   501→							texts = append(texts, text)
   502→						}
   503→					}
   504→				}
   505→			}
   506→			if len(texts) > 0 {
   507→				cleaned := textutil.StripIDEContextTags(strings.Join(texts, "\n\n"))
   508→				if cleaned != "" {
   509→					prompts = append(prompts, cleaned)
   510→				}
   511→			}
   512→		}
   513→	}
   514→	return prompts
   515→}
   516→
   517→// generateContextFromPrompts generates context.md content from a list of prompts.
   518→func generateContextFromPrompts(prompts []string) []byte {
   519→	if len(prompts) == 0 {
   520→		return nil
   521→	}
   522→
   523→	var buf strings.Builder
   524→	buf.WriteString("# Session Context\n\n")
   525→	buf.WriteString("## User Prompts\n\n")
   526→
   527→	for i, prompt := range prompts {
   528→		// Truncate very long prompts for readability
   529→		displayPrompt := prompt
   530→		if len(displayPrompt) > 500 {
   531→			displayPrompt = displayPrompt[:500] + "..."
   532→		}
   533→		buf.WriteString(fmt.Sprintf("### Prompt %d\n\n", i+1))
   534→		buf.WriteString(displayPrompt)
   535→		buf.WriteString("\n\n")
   536→	}
   537→
   538→	return []byte(buf.String())
   539→}
