   541→// CondenseSessionByID force-condenses a session by its ID and cleans up.
   542→// This is used by "entire sessions fix" to salvage stuck sessions.
   543→func (s *ManualCommitStrategy) CondenseSessionByID(sessionID string) error {
   544→	ctx := logging.WithComponent(context.Background(), "condense-by-id")
   545→
   546→	// Load session state
   547→	state, err := s.loadSessionState(sessionID)
   548→	if err != nil {
   549→		return fmt.Errorf("failed to load session state: %w", err)
   550→	}
   551→	if state == nil {
   552→		return fmt.Errorf("session not found: %s", sessionID)
   553→	}
   554→
   555→	// Open repository
   556→	repo, err := OpenRepository()
   557→	if err != nil {
   558→		return fmt.Errorf("failed to open repository: %w", err)
   559→	}
   560→
   561→	// Generate a checkpoint ID
   562→	checkpointID, err := id.Generate()
   563→	if err != nil {
   564→		return fmt.Errorf("failed to generate checkpoint ID: %w", err)
   565→	}
   566→
   567→	// Check if shadow branch exists (required for condensation)
   568→	shadowBranchName := getShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
   569→	refName := plumbing.NewBranchReferenceName(shadowBranchName)
   570→	_, refErr := repo.Reference(refName, true)
   571→	hasShadowBranch := refErr == nil
   572→
   573→	if !hasShadowBranch {
   574→		// No shadow branch means no checkpoint data to condense.
   575→		// Just clean up the state file.
   576→		logging.Info(ctx, "no shadow branch for session, clearing state only",
   577→			slog.String("session_id", sessionID),
   578→			slog.String("shadow_branch", shadowBranchName),
   579→		)
   580→		if err := s.clearSessionState(sessionID); err != nil {
   581→			return fmt.Errorf("failed to clear session state: %w", err)
   582→		}
   583→		return nil
   584→	}
   585→
   586→	// Condense the session
   587→	result, err := s.CondenseSession(repo, checkpointID, state)
   588→	if err != nil {
   589→		return fmt.Errorf("failed to condense session: %w", err)
   590→	}
   591→
   592→	logging.Info(ctx, "session condensed by ID",
   593→		slog.String("session_id", sessionID),
   594→		slog.String("checkpoint_id", result.CheckpointID.String()),
   595→		slog.Int("checkpoints_condensed", result.CheckpointsCount),
   596→	)
   597→
   598→	// Update session state: reset step count and transition to idle
   599→	state.StepCount = 0
   600→	state.CheckpointTranscriptStart = result.TotalTranscriptLines
   601→	state.Phase = session.PhaseIdle
   602→	state.LastCheckpointID = checkpointID
   603→	state.PendingCheckpointID = "" // Clear after condensation (amend handler uses LastCheckpointID)
   604→	state.PromptAttributions = nil
   605→	state.PendingPromptAttribution = nil
   606→
   607→	if err := s.saveSessionState(state); err != nil {
   608→		return fmt.Errorf("failed to save session state: %w", err)
   609→	}
   610→
   611→	// Clean up shadow branch if no other sessions need it
   612→	if err := s.cleanupShadowBranchIfUnused(repo, shadowBranchName, sessionID); err != nil {
   613→		logging.Warn(ctx, "failed to clean up shadow branch",
   614→			slog.String("shadow_branch", shadowBranchName),
   615→			slog.String("error", err.Error()),
   616→		)
   617→		// Non-fatal: condensation succeeded, shadow branch cleanup is best-effort
   618→	}
   619→
   620→	return nil
   621→}
   622→
   623→// cleanupShadowBranchIfUnused deletes a shadow branch if no other active sessions reference it.
   624→func (s *ManualCommitStrategy) cleanupShadowBranchIfUnused(repo *git.Repository, shadowBranchName, excludeSessionID string) error {
